function makeMat(region, params) {
  const mat = new THREE.MeshStandardMaterial({
    roughness: 0.45,
    metalness: 0.02,
    transparent: true,
    ...params
  });
  regionMaterials[region].push(mat);
  return mat;
}

function makeLineMat(region, color, opacity = 1) {
  const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity });
  regionMaterials[region].push(mat);
  return mat;
}

function addLine(region, a, b, color = COLORS.black, linewidth = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints([a, b]);
  const line = new THREE.Line(geom, makeLineMat(region, color, 1));
  line.material.linewidth = linewidth;
  regionGroups[region].add(line);
  return line;
}

function cylinderBetween(region, a, b, radius, color, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geom = new THREE.CylinderGeometry(radius, radius, len, 10, 1);
  const mat = makeMat(region, { color, opacity });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  regionGroups[region].add(mesh);
  return mesh;
}

function arrow(region, start, end, color, radius = 0.012) {
  cylinderBetween(region, start, end, radius, color, 1);
  const dir = new THREE.Vector3().subVectors(end, start).normalize();
  const coneLen = 0.13;
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(radius * 4.2, coneLen, 18),
    makeMat(region, { color, opacity: 1, roughness: 0.35 })
  );
  cone.position.copy(end).addScaledVector(dir, -coneLen * 0.45);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  regionGroups[region].add(cone);
  return cone;
}

function makeTailCurve(x, y0, z, upward, phase, lengthScale = 1) {
  const pts = [];
  const y1 = upward ? -0.02 : 0.02;
  for (let i = 0; i < 7; i++) {
    const t = i / 6;
    const yy = y0 + (y1 - y0) * t;
    const xx = x + 0.045 * Math.sin(phase + t * Math.PI * 2.2) * lengthScale;
    const zz = z + 0.038 * Math.cos(phase * 1.3 + t * Math.PI * 2.8) * lengthScale;
    pts.push(new THREE.Vector3(xx, yy, zz));
  }
  return new THREE.CatmullRomCurve3(pts);
}

function tubeFromCurve(region, curve, radius, color, opacity = 1, radial = 6, tubular = 18) {
