function applyMaterialHighlight(region, selected) {
  for (const mat of regionMaterials[region]) {
    if (!mat) continue;
    mat.opacity = selected ? 1 : 0.28;
    mat.transparent = true;
    if (mat.emissive) {
      if (selected) {
        if (region === "Ionic head") mat.emissive.setHex(0x00aa68);
        if (region === "Glycerol linker") mat.emissive.setHex(0x5b3f34);
        if (region === "Nonpolar tails") mat.emissive.setHex(0x7f3d32);
        mat.emissiveIntensity = 0.28;
      } else {
        mat.emissiveIntensity = 0.02;
      }
    }
    mat.needsUpdate = true;
  }
}

