function updateCutawayDepth(v) {
  const depth = Number(v);
  const y = 0.72 - depth * 1.44;
  slicePlane.position.y = y;
  sliceOutline.position.y = y;

  const distHead = Math.min(Math.abs(y - 0.72), Math.abs(y + 0.72));
  const distLink = Math.min(Math.abs(y - 0.55), Math.abs(y + 0.55));
  const distTail = Math.abs(y);
  if (currentRegion === "Ionic head" && distHead < 0.18) sliceMat.opacity = 0.34;
  else if (currentRegion === "Glycerol linker" && distLink < 0.18) sliceMat.opacity = 0.34;
  else if (currentRegion === "Nonpolar tails" && distTail < 0.48) sliceMat.opacity = 0.34;
  else sliceMat.opacity = 0.22;
}

