function makeBilayerTail(x, z, y0, upward, phase, amplitude = 1) {
  const pts = [];
  const yEnd = upward ? -0.03 : 0.03;
  for (let k = 0; k <= 7; k++) {
    const t = k / 7;
    const y = y0 + (yEnd - y0) * t;
    pts.push(new THREE.Vector3(
      x + 0.035 * Math.sin(phase + t * Math.PI * 3.1) * amplitude,
      y + 0.018 * Math.sin(phase * 1.7 + t * Math.PI * 4.4),
      z + 0.04 * Math.cos(phase * 1.1 + t * Math.PI * 3.7) * amplitude
    ));
  }
  return new THREE.CatmullRomCurve3(pts);
}

