function applyMaterialHighlight(region, selected) {
  for (const mat of regionMaterials[region]) {
    if (!mat) continue;
    const base = mat.userData.baseOpacity ?? 1;
    if (mat === sliceMat || mat === sliceOutline.material) continue;
    mat.opacity = selected ? Math.min(1, Math.max(base, 0.98)) : Math.max(0.72, base * 0.88);
    mat.transparent = true;
    if (mat.emissive) {
      mat.emissiveIntensity = selected ? 0.16 : 0.035;
    }
    mat.needsUpdate = true;
  }
  for (const obj of selectedOverlays[region]) {
    if (obj.material) {
      obj.material.opacity = selected ? (region === "Nonpolar tails" ? 0.10 : 0.16) : 0;
      obj.material.needsUpdate = true;
    }
  }
}

function setRegion(region) {
  currentRegion = region;
  if (focusSelect.value !== region) focusSelect.value = region;
  for (const name of Object.keys(regionGroups)) {
    const selected = name === region;
    applyMaterialHighlight(name, selected);
    setLabelHighlight(name, selected);
  }
}

function setSliceVisible(on, hold = true) {
