function tweenSlider(to, duration = 520) {
  const from = Number(cutSlider.value);
  const start = performance.now();
  setSliceVisible(true, false);
  function tick(now) {
    const t = Math.min(1, (now - start) / duration);
    const ease = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const v = from + (to - from) * ease;
    cutSlider.value = v.toFixed(2);
    updateCutawayDepth(v, false);
    if (t < 1) requestAnimationFrame(tick);
    else setSliceVisible(true, true);
  }
  requestAnimationFrame(tick);
}

window.goToStep = function goToStep(i) {
  const step = demoSteps[Math.max(0, Math.min(demoSteps.length - 1, i | 0))];
  focusSelect.value = step.state.mappingFocus;
  setRegion(step.state.mappingFocus);
  tweenSlider(step.state.cutawayDepth);
  narration.innerHTML = `<b>${step.title}.</b> ${step.narration}`;
  showPopup(step.title, step.narration);
};

