// @FIGURE_CODE_BEGIN
// bilayer top ionic heads → InstancedMesh SphereGeometry(0.095) green staggered, jittered, organic upper sheet with stepped missing corner
// bilayer bottom ionic heads → InstancedMesh SphereGeometry(0.095) green staggered, jittered lower sheet
// bilayer head shadows → InstancedMesh slightly offset darker green spheres
// bilayer glycerol-linker bands → two thin semi-transparent brown/tan BoxGeometry sheets under/over head layers
// bilayer upper nonpolar tails → dense pale tan CatmullRomCurve3 TubeGeometry pairs descending from y=+0.55 to y=0
// bilayer lower nonpolar tails → dense pale tan CatmullRomCurve3 TubeGeometry pairs ascending from y=-0.55 to y=0
// bilayer exposed side-wall tails → front/back/left edge wavy tan TubeGeometry curtains visible through the cutaway
// bilayer midplane contact → thin dark tan wavy Line running along y=0
// cutaway slice plane → translucent blue PlaneGeometry with blue rectangular Line outline, moved by cutawayDepth
// structural formula bonds → black/green Line segments on a camera-facing flat construction plane
// glycerol backbone labels → HTML labels CH2, CH, CH2 with vertical black bonds
// ionic head branch labels → larger green HTML labels O, P, O−, CH2CH2N+(CH3)3 plus green bonds
// ester linkage labels → black HTML labels O, C, O and double-bond lines
// structural nonpolar tails → two long pale tan wavy TubeGeometry ribbons extending right
// structural callout arrows → green and magenta cylinder/cone arrows to ionic head and nonpolar tails
// selection/highlight volumes → transparent BoxGeometry hit targets plus subtle glow overlays for three selectable regions

renderer.localClippingEnabled = true;

scene.add(new THREE.AmbientLight(0xffffff, 1.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.15);
keyLight.position.set(2.6, 4.4, 3.2);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.55);
fillLight.position.set(-4, 2.5, -2);
scene.add(fillLight);

const COLORS = {
  green: 0x39c987,
  green2: 0x24b979,
  greenDark: 0x119b63,
  greenText: 0x008c5a,
  tan: 0xc98a7a,
  tanLight: 0xd9a497,
  tanDark: 0xae6e63,
  linker: 0x967064,
  magenta: 0xff1493,
  blue: 0x8fd3ff,
  black: 0x111111
};

const regionGroups = {
  "Ionic head": new THREE.Group(),
  "Glycerol linker": new THREE.Group(),
  "Nonpolar tails": new THREE.Group()
};
scene.add(regionGroups["Ionic head"], regionGroups["Glycerol linker"], regionGroups["Nonpolar tails"]);

const regionMaterials = {
  "Ionic head": [],
  "Glycerol linker": [],
  "Nonpolar tails": []
};
const formulaLabels = {
  "Ionic head": [],
  "Glycerol linker": [],
  "Nonpolar tails": []
};
const selectedOverlays = {
  "Ionic head": [],
  "Glycerol linker": [],
  "Nonpolar tails": []
};

function makeMat(region, params) {
  const mat = new THREE.MeshStandardMaterial({
    roughness: 0.62,
    metalness: 0,
    transparent: true,
    ...params
  });
  mat.userData.baseOpacity = params.opacity ?? 1;
  mat.userData.baseColor = params.color;
  regionMaterials[region].push(mat);
  return mat;
}

function makeBasicMat(region, params) {
  const mat = new THREE.MeshBasicMaterial({ transparent: true, ...params });
  mat.userData.baseOpacity = params.opacity ?? 1;
  mat.userData.baseColor = params.color;
  regionMaterials[region].push(mat);
  return mat;
}

function makeLineMat(region, color, opacity = 1) {
  const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity });
  mat.userData.baseOpacity = opacity;
  regionMaterials[region].push(mat);
  return mat;
}

function addLine(region, a, b, color = COLORS.black, opacity = 1) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([a, b]),
    makeLineMat(region, color, opacity)
  );
  regionGroups[region].add(line);
  return line;
}

function cylinderBetween(region, a, b, radius, color, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 14, 1),
    makeMat(region, { color, opacity, roughness: 0.58 })
  );
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  regionGroups[region].add(mesh);
  return mesh;
}

function tubeFromCurve(region, curve, radius, color, opacity = 1, radial = 8, tubular = 32) {
  const mesh = new THREE.Mesh(
    new THREE.TubeGeometry(curve, tubular, radius, radial, false),
    makeMat(region, { color, opacity, roughness: 0.82 })
  );
  regionGroups[region].add(mesh);
  return mesh;
}

function arrow(region, start, end, color, radius = 0.009) {
  cylinderBetween(region, start, end, radius, color, 1);
  const dir = new THREE.Vector3().subVectors(end, start).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(radius * 4.8, 0.13, 22),
    makeMat(region, { color, opacity: 1, roughness: 0.35 })
  );
  cone.position.copy(end).addScaledVector(dir, -0.055);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  regionGroups[region].add(cone);
  return cone;
}

function jitter(i, j, s) {
  return Math.sin(i * 12.9898 + j * 78.233 + s * 37.719) * 43758.5453 % 1;
}

const slabCenterX = -3.28;
const slabLen = 4.15;
const slabDepth = 1.62;
const xMin = slabCenterX - slabLen / 2;
const zMin = -slabDepth / 2;
const dx = slabLen / 13;
const dz = slabDepth / 6;

const sphereGeom = new THREE.SphereGeometry(0.095, 28, 16);
const headMat = makeMat("Ionic head", { color: COLORS.green, emissive: 0x063f27, emissiveIntensity: 0.035, roughness: 0.36 });
const headMat2 = makeMat("Ionic head", { color: COLORS.green2, emissive: 0x063f27, emissiveIntensity: 0.03, roughness: 0.4 });
const shadowMatTop = makeMat("Ionic head", { color: COLORS.greenDark, opacity: 0.30, roughness: 0.5 });
const shadowMatBottom = makeMat("Ionic head", { color: COLORS.greenDark, opacity: 0.26, roughness: 0.5 });

const topPositions = [];
const bottomPositions = [];
for (let i = 0; i < 14; i++) {
  for (let j = 0; j < 7; j++) {
    const organicX = (j % 2) * dx * 0.45 + (jitter(i, j, 1) - 0.5) * 0.045;
    const organicZ = (jitter(i, j, 2) - 0.5) * 0.045;
    const x = xMin + i * dx + organicX;
    const z = zMin + j * dz + organicZ;
    const topWave = 0.018 * Math.sin(i * 0.72 + j * 0.9) + 0.012 * (jitter(i, j, 3) - 0.5);
    const bottomWave = 0.014 * Math.sin(i * 0.55 - j * 0.75);
    const steppedTopCut = (x < xMin + 0.90 && z > zMin + slabDepth * 0.53) ||
                          (x < xMin + 0.55 && z > zMin + slabDepth * 0.35);
    if (!steppedTopCut) topPositions.push(new THREE.Vector3(x, 0.72 + topWave, z));
    bottomPositions.push(new THREE.Vector3(x + 0.02 * Math.sin(j), -0.72 + bottomWave, z));
  }
}

const topHeads = new THREE.InstancedMesh(sphereGeom, headMat, topPositions.length);
const bottomHeads = new THREE.InstancedMesh(sphereGeom, headMat2, bottomPositions.length);
const topHeadShadow = new THREE.InstancedMesh(new THREE.SphereGeometry(0.098, 18, 10), shadowMatTop, topPositions.length);
const bottomHeadShadow = new THREE.InstancedMesh(new THREE.SphereGeometry(0.098, 18, 10), shadowMatBottom, bottomPositions.length);
const tmpM = new THREE.Matrix4();

topPositions.forEach((p, i) => {
  tmpM.makeTranslation(p.x + 0.026, p.y - 0.024, p.z + 0.020);
  topHeadShadow.setMatrixAt(i, tmpM);
  tmpM.makeTranslation(p.x, p.y, p.z);
  topHeads.setMatrixAt(i, tmpM);
});
bottomPositions.forEach((p, i) => {
  tmpM.makeTranslation(p.x + 0.026, p.y - 0.018, p.z + 0.020);
  bottomHeadShadow.setMatrixAt(i, tmpM);
  tmpM.makeTranslation(p.x, p.y, p.z);
  bottomHeads.setMatrixAt(i, tmpM);
});
topHeads.instanceMatrix.needsUpdate = true;
bottomHeads.instanceMatrix.needsUpdate = true;
topHeadShadow.instanceMatrix.needsUpdate = true;
bottomHeadShadow.instanceMatrix.needsUpdate = true;
regionGroups["Ionic head"].add(topHeadShadow, bottomHeadShadow, topHeads, bottomHeads);

const headGlowMat = makeBasicMat("Ionic head", { color: 0xb9f4d8, opacity: 0, depthWrite: false });
const topGlow = new THREE.Mesh(new THREE.BoxGeometry(slabLen * 1.02, 0.20, slabDepth * 1.02), headGlowMat);
topGlow.position.set(slabCenterX, 0.72, 0);
const bottomGlow = new THREE.Mesh(new THREE.BoxGeometry(slabLen * 1.02, 0.20, slabDepth * 1.02), headGlowMat.clone());
bottomGlow.position.set(slabCenterX, -0.72, 0);
regionGroups["Ionic head"].add(topGlow, bottomGlow);
selectedOverlays["Ionic head"].push(topGlow, bottomGlow);

const upperBand = new THREE.Mesh(
  new THREE.BoxGeometry(slabLen * 0.97, 0.052, slabDepth * 0.97),
  makeMat("Glycerol linker", { color: COLORS.linker, opacity: 0.72, roughness: 0.86 })
);
upperBand.position.set(slabCenterX, 0.555, 0);
const lowerBand = new THREE.Mesh(
  new THREE.BoxGeometry(slabLen * 0.97, 0.052, slabDepth * 0.97),
  makeMat("Glycerol linker", { color: COLORS.linker, opacity: 0.72, roughness: 0.86 })
);
lowerBand.position.set(slabCenterX, -0.555, 0);
regionGroups["Glycerol linker"].add(upperBand, lowerBand);

const linkerGlowMat = makeBasicMat("Glycerol linker", { color: 0xffd0aa, opacity: 0, depthWrite: false });
const upperOutline = new THREE.Mesh(new THREE.BoxGeometry(slabLen * 1.0, 0.10, slabDepth * 1.0), linkerGlowMat);
upperOutline.position.copy(upperBand.position);
const lowerOutline = new THREE.Mesh(new THREE.BoxGeometry(slabLen * 1.0, 0.10, slabDepth * 1.0), linkerGlowMat.clone());
lowerOutline.position.copy(lowerBand.position);
regionGroups["Glycerol linker"].add(upperOutline, lowerOutline);
selectedOverlays["Glycerol linker"].push(upperOutline, lowerOutline);

function makeBilayerTail(x, z, y0, upward, phase, amp = 1) {
  const pts = [];
  const yEnd = upward ? -0.02 : 0.02;
  for (let k = 0; k <= 8; k++) {
    const t = k / 8;
    pts.push(new THREE.Vector3(
      x + 0.044 * Math.sin(phase + t * Math.PI * 3.5) * amp + 0.012 * Math.sin(t * 19 + phase),
      y0 + (yEnd - y0) * t + 0.018 * Math.sin(phase * 1.7 + t * Math.PI * 4.8),
      z + 0.050 * Math.cos(phase * 1.1 + t * Math.PI * 3.2) * amp
    ));
  }
  return new THREE.CatmullRomCurve3(pts);
}

