function formulaTail(y, phase) {
  const pts = [];
  for (let i = 0; i <= 48; i++) {
    const t = i / 48;
    const x = 1.62 + t * 4.15;
    const wave = 0.024 * Math.sin(t * Math.PI * 8.0 + phase) + 0.010 * Math.sin(t * Math.PI * 21 + phase);
    pts.push(F(x, y + wave, 0.018 * Math.cos(t * Math.PI * 4 + phase)));
  }
  return tubeFromCurve("Nonpolar tails", new THREE.CatmullRomCurve3(pts), 0.030, COLORS.tanLight, 1, 9, 58);
}

