function setLabelHighlight(region, selected) {
  for (const entry of formulaLabels[region]) {
    entry.div.style.opacity = selected ? "1" : "0.90";
    entry.div.style.fontWeight = selected ? "700" : "";
    entry.div.style.textShadow = selected
