        ? "0 0 1px #008c5a, 0 1px 2px #fff"
        : region === "Nonpolar tails"
          ? "0 0 1px #ff1493, 0 1px 2px #fff"
          : "0 0 1px #7b5a4d, 0 1px 2px #fff"
      : "0 1px 2px #fff";
  }
}

function applyMaterialHighlight(region, selected) {
  for (const mat of regionMaterials[region]) {
    if (!mat || mat === sliceMat || mat === sliceOutline.material) continue;
    const base = mat.userData.baseOpacity ?? 1;
    mat.opacity = selected ? Math.min(1, Math.max(base, 0.98)) : Math.max(0.64, base * 0.80);
    mat.transparent = true;
    if (mat.emissive) mat.emissiveIntensity = selected ? 0.14 : 0.025;
    mat.needsUpdate = true;
  }
  for (const obj of selectedOverlays[region]) {
    if (obj.material) {
      obj.material.opacity = selected ? (region === "Ionic head" ? 0.055 : region === "Glycerol linker" ? 0.075 : 0.060) : 0;
      obj.material.needsUpdate = true;
    }
  }
}

function setRegion(region) {
  currentRegion = region;
  if (focusSelect.value !== region) focusSelect.value = region;
  for (const name of Object.keys(regionGroups)) {
    const selected = name === region;
    applyMaterialHighlight(name, selected);
    setLabelHighlight(name, selected);
  }
}

function setSliceVisible(on, hold = true) {
  clearTimeout(sliceHideTimer);
  sliceMat.opacity = on ? 0.10 : 0;
  sliceOutline.material.opacity = on ? 0.62 : 0;
  if (on && hold) {
    sliceHideTimer = setTimeout(() => {
      sliceMat.opacity = 0;
      sliceOutline.material.opacity = 0;
    }, 1300);
  }
}

function updateCutawayDepth(v, revealPlane = true) {
  const depth = Number(v);
  const y = 0.72 - depth * 1.44;
  slicePlane.position.y = y;
  sliceOutline.position.y = y;
  if (revealPlane) setSliceVisible(true, true);

  const distHead = Math.min(Math.abs(y - 0.72), Math.abs(y + 0.72));
  const distLink = Math.min(Math.abs(y - 0.555), Math.abs(y + 0.555));
  const distTail = Math.abs(y);
  if (distHead < 0.14) sliceOutline.material.color.setHex(0x20b978);
  else if (distLink < 0.13) sliceOutline.material.color.setHex(0xa77b61);
  else if (distTail < 0.50) sliceOutline.material.color.setHex(0xd28e7e);
  else sliceOutline.material.color.setHex(0x2aa7e8);
}

